// 1. Ambil data dari output GOWA "Get Connection Status"
// Kita pakai $input.first() biar aman dan cepat
const data = $input.first().json.results || {};

// 2. Logika Status (Biar ada emojinya)
const isConnected = data.is_connected;
const isLoggedIn = data.is_logged_in;

// Tentukan Header (Hijau kalau aman, Merah kalau putus)
const headerStatus = isConnected && isLoggedIn ? "🟢 SYSTEM ONLINE" : "🔴 SYSTEM OFFLINE";

// Bersihkan format Device ID (Hilangkan bagian @s.whatsapp.net yang panjang)
// Dari "62878...:56@s.whatsapp.net" menjadi "62878..."
let deviceNumber = "-";
if (data.device_id) {
  deviceNumber = data.device_id.split(':')[0]; // Ambil angka depan sebelum titik dua
}

// 3. Susun Template Pesan
const message = `📊 *STATUS MONITOR*
━━━━━━━━━━━━━━━━━━━
${headerStatus}

📡 *Connection Info:*
├  📶 **Connected:** ${isConnected ? '✅ Yes' : '❌ No'}
├  🔑 **Session:** ${isLoggedIn ? 'Active' : 'Expired'}
└  📱 **Device:** \`${deviceNumber}\`

🕒 *Last Check:*
${new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' })}
━━━━━━━━━━━━━━━━━━━
_Bot is running on GOWA API Gateway_`;

// 4. Return data text_status
return {
  json: {
    text_status: message
  }
};

// 1. Ambil Jam Server untuk Greeting Otomatis
// Pastikan jam server n8n sesuai WIB (atau sesuaikan offsetnya)
const now = new Date();
// Konversi ke WIB (UTC+7) secara manual biar aman
const offset = 7;
const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
const serverDate = new Date(utc + (3600000 * offset));
const jam = serverDate.getHours();

let salam = "Malam";
if (jam >= 4 && jam < 11) salam = "Pagi ☀️";
else if (jam >= 11 && jam < 15) salam = "Siang 🌤️";
else if (jam >= 15 && jam < 18) salam = "Sore 🌇";

// 2. Buat Template Pesan Menu Lengkap
// List ini disesuaikan dengan Switch Command yang ada di JSON Mas Eka
const menuText = `👋 *Halo, Selamat ${salam}, Kak!*\n
Saya adalah asisten pribadi Mas Eka. Berikut adalah daftar perintah lengkap yang tersedia:\n
⏰ *REMINDER SYSTEM (BARU)*
━━━━━━━━━━━━━━━━━━━
👉 *!ingatkan [nomor] [waktu] [pesan]*
   _Contoh: !ingatkan 62812xxx 05:00 Bangun pagi_
   _Contoh: !ingatkan 10m Cek Server_
👉 *!ingatkan list* : Cek daftar pengingat aktif
👉 *!ingatkan hapus [ID]* : Hapus jadwal pengingat\n
👑 *VIP MANAGEMENT*
━━━━━━━━━━━━━━━━━━━
👉 *!addvip [nomor]* : Tambah user VIP (Admin)
👉 *!removevip [nomor]* : Hapus user VIP (Admin)
👉 *!vvip* : Cek daftar seluruh member VIP\n
🛠️ *SYSTEM TOOLS*
━━━━━━━━━━━━━━━━━━━
👉 *!ping* : Cek kecepatan respon bot
👉 *!status* : Cek koneksi server & sesi WA
👉 *!device* : Cek info perangkat yang terhubung\n
🧠 *FITUR AI (GEMINI)*
━━━━━━━━━━━━━━━━━━━
💬 *Chat Langsung* : Tanya apa saja (Japri)
📸 *Kirim Foto* : Analisis gambar (Coming Soon)
🎥 *Kirim Video* : Analisis video (Coming Soon)\n
💡 _Tips: Ketik perintah tanpa tanda kurung [ ]._
\nPowered by *n8n & Gemini AI* 🚀`;

// 3. Return hasilnya ke node GOWA
return {
  json: {
    text_menu: menuText
  }
};

// 1. Ambil data langsung dari Input yang masuk ke node ini (Lebih Cepat)
// Kita pakai try-catch biar kalau data kosong, dia tidak hang/error
let incomingTime;
try {
  // Coba ambil timestamp dari pesan yang masuk
  const inputData = $input.first().json;
  incomingTime = inputData.timestamp ? new Date(inputData.timestamp).getTime() : Date.now();
} catch (error) {
  // Kalau error/data kosong, anggap waktu sekarang
  incomingTime = Date.now();
}

const processTime = Date.now();

// 2. Hitung Latency
let latency = processTime - incomingTime;
if (latency < 0) latency = 0;

// 3. Format Pesan
const reply = `🏓 *Pong!*

🚀 *Speed:* ${latency}ms
🕒 *Server Time:* ${new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' })}
💻 *Status:* Online & Ready`;

return {
  json: {
    text_reply: reply
  }
};

// 1. Ambil data results dari input sebelumnya
// Kita pakai array kosong [] sebagai cadangan kalau data tidak ada
const devices = $input.first().json.results || [];

// 2. Siapkan variabel penampung pesan
let message = "📱 *DEVICE INFORMATION*\n━━━━━━━━━━━━━━━━━━━";

if (devices.length === 0) {
  message += "\n❌ *No device found.*";
} else {
  // 3. Looping data device (jika ada lebih dari 1)
  devices.forEach((item, index) => {
    const name = item.name || "Unknown";
    const rawId = item.device || "-";

    // Bersihkan format nomor HP (Hilangkan :56@s.whatsapp.net dsb)
    // Ambil angka sebelum tanda titik dua (:) atau sebelum (@)
    let cleanNumber = rawId.split(':')[0]; 
    if (cleanNumber.includes('@')) cleanNumber = cleanNumber.split('@')[0];

    message += `\n\n🤖 *Device ${index + 1}*`;
    message += `\n👤 *Name:* ${name}`;
    message += `\n📞 *Number:* \`${cleanNumber}\``; // Pakai format monospace
    message += `\n🆔 *Raw ID:* ${rawId}`;
  });
}

// 4. Tambahkan Footer
message += `\n\n━━━━━━━━━━━━━━━━━━━\n_Total Devices: ${devices.length}_`;

// 5. Return hasil text untuk dikirim
return {
  json: {
    text_device: message
  }
};

// === BAGIAN 1: PEMBURU DATA YANG LEBIH PINTAR ===
let textToScan = "";

// Ambil data input
const inputData = $input.first().json;
const codeData = $('code').first().json || {};

// PRIORITAS PENGAMBILAN DATA (Pilih SATU saja biar gak duplikat)
if (inputData.originalMessage) {
    textToScan = inputData.originalMessage;
} else if (codeData.originalMessage) {
    textToScan = codeData.originalMessage;
} else if (inputData.commandArgs) {
    // Kalau cuma ada args, kita tambahkan prefix palsu biar regex command jalan
    textToScan = "!addvip " + inputData.commandArgs; 
} else {
    // Fallback terakhir
    textToScan = inputData.body?.message?.text || "";
}

// Ubah ke huruf kecil semua
const fullText = textToScan.toLowerCase();

// === BAGIAN 2: LOGIKA EKSTRAKSI ===

// A. Cari Nomor HP (Simpan versi RAW dan versi DB)
let phone = "";
let rawNumberFound = ""; // Ini teks angka asli yang ditemukan di chat

const numberMatch = fullText.match(/\d{10,15}/);

if (numberMatch) {
    rawNumberFound = numberMatch[0]; // Misal: "08123456789"

    // Normalisasi untuk Database (62...)
    let dbNumber = rawNumberFound;
    if (dbNumber.startsWith("08")) dbNumber = "62" + dbNumber.substring(1);
    if (dbNumber.startsWith("62")) phone = dbNumber;
}

// B. Cari Fitur
let feature = "all";
if (fullText.includes("image")) feature = "image";
else if (fullText.includes("video")) feature = "video";

// C. Cari Alasan (PEMBERSIHAN TOTAL)
// Kita hapus: Command, Nomor HP Asli (bukan yg sudah diubah ke 62), dan Fitur
let cleanReason = fullText
    .replace(/!addvip|addvip|!removevip|removevip|!vvip/gi, "") 
    .replace(rawNumberFound, "") // Hapus angka "08..." dari teks
    .replace(feature, "")
    .replace(/[^a-z0-9\s]/g, "") // Hapus simbol aneh
    .replace(/\s+/g, " ")        // Hapus spasi berlebih/double space
    .trim();

// Default alasan
let reason = cleanReason.length > 2 ? cleanReason : "VIP Member Access";

// === BAGIAN 3: TENTUKAN MODE ===
let mode = "view";
const isRemove = fullText.includes("!removevip") || fullText.includes("removevip");

if (isRemove && phone !== "") {
    mode = "delete";
} else if (phone !== "") {
    mode = "add";
}

return {
    json: {
        mode: mode,
        feature: feature,
        phone: phone,
        reason: reason,
        timestamp: new Date().toISOString(),
        _debug_read: textToScan
    }
};

// Ambil semua data dari node Table sebelumnya
const rows = $input.all();

// Cek jika database kosong
if (rows.length === 0) {
  return { json: { reply_message: "📭 *Daftar VIP Kosong.*\nBelum ada member yang terdaftar." } };
}

// Susun Pesan Header
let msg = "💎 *DAFTAR VIP MEMBER*\n━━━━━━━━━━━━━━━━━━━\n";

// Looping data (Menyusun list ke bawah)
rows.forEach((item, index) => {
  const data = item.json;
  const phone = data.phone || "Tanpa Nomor";
  const reason = data.reason || "VIP Access";

  // Tampilan per user
  msg += `${index + 1}. 👤 \`${phone}\`\n`;
  msg += `   └ 📝 ${reason}\n`;
});

// Footer (Total data)
msg += `\n━━━━━━━━━━━━━━━━━━━`;
msg += `\n📊 *Total:* ${rows.length} Member Active`;

return { json: { reply_message: msg } };

// Ambil data yang baru saja masuk ke database
const data = $input.first().json;

// Ambil info (fallback ke default kalau kosong)
const phone = data.phone || "Member Baru";
const reason = data.reason || "VIP Access";

// Susun Pesan Sukses
let msg = `✅ *VIP MEMBER DITAMBAHKAN*`;
msg += `\n━━━━━━━━━━━━━━━━━━━`;
msg += `\n👤 *Target:* \`${phone}\``;
msg += `\n📝 *Note:* ${reason}`;
msg += `\n\n_Sekarang nomor ini memiliki akses prioritas ke fitur bot._`;

return { json: { reply_message: msg } };

// Ambil nomor HP dari node parser awal (vipuser)
// Ini lebih aman daripada ambil dari output delete yang kadang kosong
let phone = "Target";

try {
    // Kita panggil data dari node 'vipuser'
    phone = $('vipuser').item.json.phone;
} catch (e) {
    // Fallback kalau gagal, ambil dari input langsung
    phone = $input.first().json.phone || "Unknown User";
}

// Susun Pesan Hapus
let msg = `🗑️ *VIP MEMBER DIHAPUS*`;
msg += `\n━━━━━━━━━━━━━━━━━━━`;
msg += `\n👤 *Target:* \`${phone}\``;
msg += `\n✅ *Status:* Akses VIP telah dicabut dari database.`;

return { json: { reply_message: msg } };

const items = $input.all();
const result = [];

for (const item of items) {
  let args = item.json.commandArgs || ""; 
  // Contoh Input: "628123456789 05:00 tiap 1d Sayang bangun"

  const senderPhone = item.json.userPhone;
  let targetPhone = senderPhone; // Default: Kirim ke diri sendiri

  // --- 1. Mode CRUD (List/Hapus) ---
  const firstWord = args.split(" ")[0].toLowerCase();

  if (firstWord === 'list') {
    result.push({ json: { mode: "LIST", phone: senderPhone } });
    continue;
  }
  if (firstWord === 'hapus') {
    const idToDelete = args.split(" ")[1];
    result.push({ json: { mode: "DELETE", phone: senderPhone, id_hapus: idToDelete } });
    continue;
  }

  // --- 2. Cek Deteksi Nomor HP Tujuan ---
  // Regex: Cari angka 10-15 digit di awal kalimat diikuti spasi
  const phoneRegex = /^(\d{10,15})\s+(.+)$/;
  const phoneMatch = args.match(phoneRegex);

  if (phoneMatch) {
    targetPhone = phoneMatch[1]; // Ambil nomor target
    args = phoneMatch[2];        // Update sisa pesan (buang nomornya)
  }

  // --- 3. Mode Parsing Waktu (Alarm & Timer) ---
  let targetTime = new Date();
  let durasiInfo = "";
  let intervalStr = "";
  let pesan = "";
  let validFormat = false;

  // Regex A: Jam Dinding (05:00, 23.30)
  const regexAbsolut = /^(?:jam\s+)?(\d{1,2})[:.](\d{2})(?:\s+(?:tiap|setiap|every)\s+(\d+[mjh]))?\s+(.+)$/i;

  // Regex B: Timer Durasi (10m, 1h)
  const regexRelatif = /^(\d+[mjh])(?:\s+(?:tiap|setiap|every)\s+(\d+[mjh]))?\s+(.+)$/i;

  const matchAbsolut = args.match(regexAbsolut);
  const matchRelatif = args.match(regexRelatif);

  if (matchAbsolut) {
    // === Logic Alarm (FIX TIMEZONE WIB) ===
    validFormat = true;
    const jam = parseInt(matchAbsolut[1]);
    const menit = parseInt(matchAbsolut[2]);
    intervalStr = matchAbsolut[3] || "";
    pesan = matchAbsolut[4];

    // Trik: Kita manipulasi waktu seolah-olah server ada di Jakarta
    const now = new Date();
    const wibStr = now.toLocaleString("en-US", { timeZone: "Asia/Jakarta" });
    const nowWIB = new Date(wibStr); 

    // Buat object tanggal target berbasis komponen WIB
    const targetWIB = new Date(nowWIB);
    targetWIB.setHours(jam);
    targetWIB.setMinutes(menit);
    targetWIB.setSeconds(0);

    // Cek apakah jam target sudah lewat di WIB?
    if (targetWIB <= nowWIB) {
      targetWIB.setDate(targetWIB.getDate() + 1); // Besok
      durasiInfo = `Besok jam ${jam}:${menit < 10 ? '0'+menit : menit} WIB`;
    } else {
      durasiInfo = `Hari ini jam ${jam}:${menit < 10 ? '0'+menit : menit} WIB`;
    }

    // KONVERSI BALIK KE UTC (PENTING UNTUK DATABASE)
    // Karena targetWIB tadi kita set "jam 2" padahal server UTC, 
    // kita harus kurangi 7 jam supaya pas disimpan ke DB nilainya benar.
    const offset = 7 * 60 * 60 * 1000; // 7 Jam dalam milidetik
    targetTime = new Date(targetWIB.getTime() - offset);

  } else if (matchRelatif) {
    // === Logic Timer (Hitung Mundur) ===
    validFormat = true;
    const durasiRaw = matchRelatif[1];
    intervalStr = matchRelatif[2] || "";
    pesan = matchRelatif[3];

    const amount = parseInt(durasiRaw);
    const unit = durasiRaw.slice(-1).toLowerCase();

    if (unit === 'm') targetTime.setMinutes(targetTime.getMinutes() + amount);
    if (unit === 'j' || unit === 'h') targetTime.setHours(targetTime.getHours() + amount);
    if (unit === 'd') targetTime.setDate(targetTime.getDate() + amount);

    durasiInfo = `${durasiRaw} lagi`;
  }

  // --- 4. Output Result ---
  if (validFormat) {
    // Laporan Balasan
    let replyText = `✅ *JADWAL TERSIMPAN!*`;
    replyText += `\n🎯 Target: ${targetPhone}`;
    replyText += `\n⏰ Waktu: ${durasiInfo}`;
    if (intervalStr) replyText += `\n🔄 Ulangi: Tiap ${intervalStr}`;
    replyText += `\n📝 Isi Pesan: "${pesan}"`;

    result.push({
      json: {
        mode: "ADD",
        status: "SUCCESS",
        phone: targetPhone,
        message: pesan,
        send_at: targetTime.toISOString(),
        interval: intervalStr,
        db_status: "PENDING",
        reply_text: replyText
      }
    });
  } else {
    result.push({
      json: {
        mode: "ERROR",
        reply_text: "⚠️ *Format Salah!*\n\n👉 *Untuk Pacar:* !ingatkan [Nomor] 05:00 tiap 1d Sayang bangun\n👉 *Untuk Sendiri:* !ingatkan 10m Cek Server"
      }
    });
  }
}

return result;

const items = $input.all();
const result = [];

for (const item of items) {
  const data = item.json;

  // Format Waktu biar enak dibaca (WIB)
  const dateObj = new Date(data.send_at);
  const options = { 
    timeZone: 'Asia/Jakarta', 
    weekday: 'long', 
    day: 'numeric', 
    month: 'long', 
    hour: '2-digit', 
    minute: '2-digit' 
  };
  const waktuCantik = dateObj.toLocaleDateString('id-ID', options);

  const msg = `✅ *PENGINGAT BERHASIL DISIMPAN!*
━━━━━━━━━━━━━━━━━━━
📝 *Pesan:*
"${data.message}"

⏰ *Waktu Eksekusi:*
${waktuCantik} WIB

🎯 *Target:* ${data.phone}
🔄 *Ulang:* ${data.interval ? data.interval : "(Sekali Jalan)"}
━━━━━━━━━━━━━━━━━━━
_Bot akan mengirim pesan tepat waktu._ 😎`;

  result.push({ json: { reply_message: msg } });
}

return result;

const items = $input.all();

// Cek jika tidak ada data (Array kosong atau properti kosong)
if (items.length === 0 || !items[0].json.id) {
  return [{
    json: {
      reply_message: "📭 *Jadwal Kosong!*\n\nTidak ada pengingat yang aktif saat ini.\nKetik `!ingatkan [waktu] [pesan]` untuk membuat baru."
    }
  }];
}

let msg = `📋 *DAFTAR PENGINGAT AKTIF*
━━━━━━━━━━━━━━━━━━━\n`;

items.forEach((item, index) => {
  const data = item.json;

  // Hanya tampilkan yang statusnya PENDING
  if (data.status === 'PENDING') {
    // Format tanggal singkat
    const dateObj = new Date(data.send_at);
    const tgl = dateObj.toLocaleDateString('id-ID', { day: 'numeric', month: 'short' });
    const jam = dateObj.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Jakarta' });

    msg += `*${index + 1}. ID: ${data.id}* ${data.interval ? '🔄' : '⚡'}
📅 ${tgl} | ⏰ ${jam} WIB
📝 _"${data.message}"_
---------------------------\n`;
  }
});

msg += `\n💡 *Tips:* Ketik \`!ingatkan hapus [ID]\` untuk membatalkan.`;

return [{ json: { reply_message: msg } }];

const items = $input.all();
// Kita ambil ID yang dihapus dari input node Switch sebelumnya
// Karena node Delete kadang tidak mengembalikan data ID yang dihapus
const idHapus = $('Hitung_Waktu').item.json.id_hapus || "Target"; 

return [{
  json: {
    reply_message: `🗑️ *PENGHAPUSAN SUKSES*
━━━━━━━━━━━━━━━━━━━
Data dengan ID *${idHapus}* telah dihapus dari sistem. 

Bot tidak akan mengirimkan pesan pengingat tersebut.`
  }
}];

// 1. Ambil data dari Node HTTP Request sebelumnya
// Struktur data BMKG: { Infogempa: { gempa: { ... } } }
const rawData = $input.first().json;

// Cek apakah data valid
if (!rawData.Infogempa || !rawData.Infogempa.gempa) {
  return { json: { reply_message: "⚠️ Maaf, gagal mengambil data BMKG saat ini." } };
}

const data = rawData.Infogempa.gempa;

// 2. Ambil Link Gambar Peta (Shakemap)
// BMKG kasih nama file doang, kita harus gabungin sama URL base-nya
const imageBaseURL = "https://data.bmkg.go.id/DataMKG/TEWS/";
const imageLink = imageBaseURL + data.Shakemap;

// 3. Susun Pesan Laporan
let msg = `🌋 *INFO GEMPA TERKINI (BMKG)*
━━━━━━━━━━━━━━━━━━━
📅 *Waktu:* ${data.Tanggal} | ${data.Jam}
📉 *Magnitudo:* ${data.Magnitude}
🌊 *Kedalaman:* ${data.Kedalaman}
📍 *Lokasi:* ${data.Wilayah}
(Lintang: ${data.Lintang}, Bujur: ${data.Bujur})

⚠️ *Potensi:* ${data.Potensi}
━━━━━━━━━━━━━━━━━━━
🌐 *Lihat Peta:* ${imageLink}`;

// 4. Return data untuk dikirim GOWA
return {
  json: {
    reply_message: msg,
    image_url: imageLink // Siapa tau Mas mau kirim sebagai Gambar nanti
  }
};

// Ambil data dari Node HTTP Request
const data = $input.first().json;

// Cek apakah data valid (Kalau kota ngawur, biasanya error)
if (!data.current_condition || !data.nearest_area) {
  return { json: { reply_message: "⚠️ Kota tidak ditemukan. Coba ketik nama kota yang jelas, misal: `!cuaca Medan`" } };
}

// 1. Ambil Data Lokasi
const area = data.nearest_area[0];
const kota = area.areaName[0].value;
const negara = area.country[0].value;

// 2. Ambil Data Cuaca Saat Ini
const current = data.current_condition[0];
const suhu = current.temp_C;
const rasa = current.FeelsLikeC;
const deskripsi = current.lang_id[0].value; // Deskripsi Bahasa Indonesia
const kelembapan = current.humidity;
const angin = current.windspeedKmph;

// 3. Icon Cuaca (Manual Mapping biar cantik)
let icon = "☁️";
const descLower = deskripsi.toLowerCase();
if (descLower.includes("cerah") || descLower.includes("sunny")) icon = "☀️";
else if (descLower.includes("berawan") || descLower.includes("cloud")) icon = "🌥️";
else if (descLower.includes("hujan") || descLower.includes("rain")) icon = "🌧️";
else if (descLower.includes("petir") || descLower.includes("thunder")) icon = "⛈️";
else if (descLower.includes("kabut") || descLower.includes("fog")) icon = "🌫️";

// 4. Susun Pesan
let msg = `🌤️ *LAPORAN CUACA TERKINI*
━━━━━━━━━━━━━━━━━━━
📍 *Lokasi:* ${kota}, ${negara}
🌡️ *Suhu:* ${suhu}°C (Terasa ${rasa}°C)
${icon} *Kondisi:* ${deskripsi}

💧 *Kelembapan:* ${kelembapan}%
💨 *Angin:* ${angin} km/h
━━━━━━━━━━━━━━━━━━━
_Data powered by bmkg.go.id_`;

// 5. Return ke GOWA
return {
  json: {
