// 1. Ambil data dengan cara yang lebih aman
const inputData = $input.first().json;
const cityId = inputData.cityId;
const cityName = inputData.cityName;

// Ambil chatId dari node paling awal (Webhook) biar gak ilang
const chatId = $('code').item.json.chatId; 

// 2. Cek kalau CityID kosong, jangan lanjut
if (!cityId) {
  return {
    json: {
      error: true,
      reply_message: "⚠️ CityID tidak ditemukan. Pastikan Node pencarian kota berhasil dulu, Mas!",
      chatId: chatId
    }
  };
}

// 3. Buat format tanggal (YYYY/MM/DD)
const date = new Date();
const y = date.getFullYear();
const m = String(date.getMonth() + 1).padStart(2, '0');
const d = String(date.getDate()).padStart(2, '0');
const datePath = `${y}/${m}/${d}`;

const url = `https://api.myquran.com/v2/sholat/jadwal/${cityId}/${datePath}`;

try {
  // 4. Pakai Axios (untuk n8n versi lama)
  const axios = require('axios');
  const response = await axios.get(url);
  const result = response.data;

  if (!result.status) {
    throw new Error("API MyQuran memberikan respon error.");
  }

  const jadwal = result.data.jadwal;

  let msg = `🕌 *JADWAL SHOLAT ${cityName}*
📅 *${jadwal.tanggal}*
━━━━━━━━━━━━━━━━━━━
✨ Imsak: ${jadwal.imsak}
🌅 Subuh: ${jadwal.subuh}
☀️ Terbit: ${jadwal.terbit}
🌤️ Duha: ${jadwal.dhuha}
🕛 Dzuhur: ${jadwal.dzuhur}
🕒 Ashar: ${jadwal.ashar}
🌆 Maghrib: ${jadwal.maghrib}
🌃 Isya: ${jadwal.isya}
━━━━━━━━━━━━━━━━━━━
_Tetap semangat melayani, Gemini!_ 🚀`;

  return {
    json: {
      reply_message: msg,
      chatId: chatId
    }
  };

} catch (error) {
  return {
    json: {
      error: true,
      reply_message: `❌ *ERROR TEKNIS:* ${error.message}\n🔗 *URL:* ${url}`,
      chatId: chatId
    }
  };
}

const items = $input.all();
const results = [];
for (const item of items) {
  const d = item.json;
  const cmd = d.command?.command || "";
  const args = d.command?.args || "";
  const fullArgs = d.command?.fullArgs || "";
  const argsArray = d.command?.argsArray || [];
  const chatId = d.chatId || "";
  const senderPhone = d.senderPhone || "";
  const messageText = d.messageText || "";
  const normalizedText = d.normalizedText || "";
  const messageId = d.messageId || "";
  const pushName = d.pushName || "";
  const isGroup = d.isGroup || false;
  const messageType = d.messageType || "text";
  const mediaUrl = d.mediaUrl || "";
  const caption = d.caption || "";
  const quotedText = d.quotedText || "";
  const isVIP = d.isVIP || false;
  const isAdmin = d.isAdmin || false;
  const timestamp = d.timestamp || Date.now();
  const processedAt =
    d.processedAt ||
    new Date().toLocaleString("id-ID", { timeZone: "Asia/Jakarta" });
  results.push({
    json: {
      command: cmd,
      commandArgs: args,
      commandFullArgs: fullArgs,
      commandArgsArray: argsArray,
      chatId: chatId,
      userPhone: senderPhone,
      messageText: messageText,
      normalizedMessage: normalizedText,
      messageId: messageId,
      pushName: pushName,
      isGroup: isGroup,
      messageType: messageType,
      mediaUrl: mediaUrl,
      caption: caption,
      quotedText: quotedText,
      isVIP: isVIP,
      isAdmin: isAdmin,
      timestamp: timestamp,
      processedAt: processedAt,
      mode: "",
      phone: "",
      feature: "all",
      reason: "",
      originalMessage: messageText,
      _rawInput: d,
    },
  });
}
return results;
